  vertexShader: `
    varying vec2 vUv;
    varying float vY;
    void main() {
      vUv = uv;
      vY = position.y;
      gl_Position = projectionMatrix*modelViewMatrix*vec4(position,1.0);
    }
  `,
  fragmentShader: `
    uniform float time;
    uniform vec3 color;
    varying vec2 vUv;
    varying float vY;
    void main() {
      float scanline = step(0.5,fract(vY*20.0-time*3.0));
      float edge = smoothstep(0.0,0.05,vUv.x)*smoothstep(0.0,0.05,1.0-vUv.x)
