      float flicker = 0.85+0.15*sin(time*17.3);
      gl_FragColor = vec4(color*scanline*flicker*edge,0.7*scanline*edge);
    }
  `,
  transparent: True,
  side: THREE.DoubleSide,
  depthWrite: False
});
