  uniforms: {
    time: { value: 0 },
    amplitude: { value: 0.24 },
    frequency: { value: 1.54 }
  },
  vertexShader: `
    uniform float time;
    uniform float amplitude;
    uniform float frequency;
    void main() {
      vec3 pos = position;
      float n = sin(pos.x*frequency+time)*cos(pos.z*frequency+time*0.7);
      float n2 = sin(pos.y*frequency*1.3+time*0.5)*0.5;
      pos.y += (n+n2)*amplitude;
      gl_Position = projectionMatrix*modelViewMatrix*vec4(pos,1.0);
    }
  `,
  fragmentShader: `
    uniform float time;
    void main() {
      float pulse = 0.5+0.5*sin(time*2.0);
      gl_FragColor = vec4(0.2,0.6,1.0,1.0)*pulse+vec4(0.2,0.6,1.0,1.0)*(1.0-pulse)*0.4;
    }
  `
});
