  },
  vertexShader: `
    uniform float time;
    uniform float amplitude;
    uniform float frequency;
    void main() {
      vec3 pos = position;
      float n = sin(pos.x*frequency+time)*cos(pos.z*frequency+time*0.7);
      float n2 = sin(pos.y*frequency*1.3+time*0.5)*0.5;
